'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useStudentStore, Course, Lesson } from '@/store/student-store';

interface CoursePlayerClientProps {
  initialCourse: Course;
  allCourses: Course[];
}

export default function CoursePlayerClient({ initialCourse, allCourses }: CoursePlayerClientProps) {
  const router = useRouter();
  const initialize = useStudentStore(state => state.initialize);
  const storeCourses = useStudentStore(state => state.courses);
  const markLessonComplete = useStudentStore(state => state.markLessonComplete);

  useEffect(() => {
    // Initialize the store if it's empty (e.g. hard refresh on this page)
    if (storeCourses.length === 0) {
      initialize(null as any, allCourses);
    }
  }, [allCourses, initialize, storeCourses.length]);

  // Use the live course from the store to ensure progress reflects immediately
  const liveCourse = storeCourses.find(c => c.id === initialCourse.id) || initialCourse;
  
  // Auto-select the next incomplete lesson, or the first lesson if all completed
  const firstIncomplete = liveCourse.lessons.find((l: Lesson) => !l.isCompleted);
  const [activeLesson, setActiveLesson] = useState<Lesson>(firstIncomplete || liveCourse.lessons[0]);

  // Update active lesson if course data changes and current active lesson becomes completed
  // (Optional: auto-advance to next lesson)
  const handleMarkComplete = () => {
    markLessonComplete(liveCourse.id, activeLesson.id);
    
    // Find next incomplete lesson to auto-advance
    const currentIndex = liveCourse.lessons.findIndex((l: Lesson) => l.id === activeLesson.id);
    if (currentIndex < liveCourse.lessons.length - 1) {
      setActiveLesson(liveCourse.lessons[currentIndex + 1]);
    }
  };

  return (
    <div className="flex flex-col gap-6 h-[calc(100vh-140px)]">
      {/* Header */}
      <header className="flex items-center gap-4">
        <button onClick={() => router.back()} className="w-10 h-10 flex items-center justify-center rounded-full bg-surface-container hover:bg-surface-container-high transition-colors text-on-surface">
          <span className="material-symbols-outlined">arrow_back</span>
        </button>
        <div>
          <h1 className="font-display text-[24px] md:text-[32px] font-bold text-primary leading-tight">{liveCourse.title}</h1>
          <p className="text-on-surface-variant text-sm flex items-center gap-2">
            <span className="material-symbols-outlined text-[16px]">person</span> {liveCourse.tutor}
          </p>
        </div>
      </header>

      <div className="flex flex-col lg:flex-row gap-6 h-full overflow-hidden">
        {/* Main Player Area */}
        <div className="flex-1 flex flex-col gap-6 overflow-y-auto pr-2 pb-8">
          <div className="bg-black w-full aspect-video rounded-2xl overflow-hidden shadow-ambient relative group">
            {activeLesson.isLockedByTutor ? (
              <div className="absolute inset-0 flex items-center justify-center text-white flex-col gap-6 p-8 text-center bg-surface-variant/10 backdrop-blur-sm">
                <span className="material-symbols-outlined text-[80px] text-error drop-shadow-md">lock</span>
                <div className="max-w-md">
                  <h3 className="font-headline text-[24px] font-bold mb-2">Lesson Locked</h3>
                  <p className="text-white/80">{activeLesson.lockMessage || "This lesson is locked by your tutor. Please complete pending assignments to proceed."}</p>
                </div>
              </div>
            ) : activeLesson.videoUrl ? (
              <iframe 
                width="100%" 
                height="100%" 
                src={activeLesson.videoUrl} 
                title="YouTube video player" 
                frameBorder="0" 
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" 
                allowFullScreen
                className="w-full h-full"
              ></iframe>
            ) : (
              <div className="absolute inset-0 flex items-center justify-center text-white flex-col gap-4">
                <span className="material-symbols-outlined text-[64px] opacity-50">play_circle</span>
                <p>No video available for this lesson.</p>
              </div>
            )}
          </div>

          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-ambient border border-outline-variant/30 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-6">
            <div>
              <h2 className="font-headline text-[24px] font-bold text-on-surface mb-2">{activeLesson.title}</h2>
              <p className="text-on-surface-variant text-sm flex items-center gap-2">
                <span className="material-symbols-outlined text-[16px]">schedule</span> {activeLesson.duration}
              </p>
            </div>
            
            <button 
              onClick={handleMarkComplete}
              disabled={activeLesson.isCompleted || activeLesson.isLockedByTutor}
              className={`px-6 py-3 rounded-xl font-label-sm font-bold flex items-center gap-2 transition-all shadow-sm ${
                activeLesson.isLockedByTutor
                  ? 'bg-surface-container-high text-on-surface-variant cursor-not-allowed opacity-50'
                  : activeLesson.isCompleted 
                  ? 'bg-secondary-container text-on-secondary-container opacity-70 cursor-default' 
                  : 'bg-primary text-on-primary hover:bg-primary/90 hover:shadow-md'
              }`}
            >
              <span className="material-symbols-outlined">
                {activeLesson.isLockedByTutor ? 'lock' : activeLesson.isCompleted ? 'check_circle' : 'task_alt'}
              </span>
              {activeLesson.isLockedByTutor ? 'Locked' : activeLesson.isCompleted ? 'Completed' : 'Mark as Complete'}
            </button>
          </div>
          
          <div className="bg-surface-container-lowest p-6 rounded-2xl shadow-ambient border border-outline-variant/30">
             <h3 className="font-headline text-[18px] font-bold text-on-surface mb-4">Lesson Materials</h3>
             <ul className="flex flex-col gap-3">
               <li className="flex items-center justify-between p-3 bg-surface-container-low rounded-lg hover:bg-surface-container transition-colors">
                  <div className="flex items-center gap-3">
                     <span className="material-symbols-outlined text-error">picture_as_pdf</span>
                     <span className="text-sm font-medium text-on-surface">Lesson Notes.pdf</span>
                  </div>
                  <button className="text-primary hover:bg-primary-container p-2 rounded-full transition-colors flex items-center justify-center">
                    <span className="material-symbols-outlined text-[20px]">download</span>
                  </button>
               </li>
             </ul>
          </div>
        </div>

        {/* Sidebar - Lesson List */}
        <div className="w-full lg:w-[350px] flex flex-col bg-surface-container-lowest rounded-2xl shadow-ambient border border-outline-variant/30 overflow-hidden flex-shrink-0 lg:h-full">
          <div className="p-4 border-b border-outline-variant/30 bg-surface-container-low flex justify-between items-center">
            <h3 className="font-headline text-[18px] font-bold text-on-surface">Course Content</h3>
            <span className="text-sm font-medium text-primary bg-primary-container px-2 py-1 rounded">
              {liveCourse.progress}%
            </span>
          </div>
          <div className="w-full bg-surface-container-high h-1">
            <div 
              className="bg-primary h-1 transition-all duration-500" 
              style={{ width: `${liveCourse.progress}%` }}
            ></div>
          </div>
          <ul className="flex-1 overflow-y-auto p-2 flex flex-col gap-1">
            {liveCourse.lessons.map((lesson: Lesson, index: number) => (
              <li key={lesson.id}>
                <button
                  onClick={() => setActiveLesson(lesson)}
                  className={`w-full text-left p-3 rounded-xl flex items-start gap-3 transition-colors ${
                    activeLesson.id === lesson.id 
                      ? 'bg-primary-container text-on-primary-container' 
                      : 'hover:bg-surface-container-low text-on-surface'
                  }`}
                >
                  <div className="mt-0.5">
                    {lesson.isLockedByTutor ? (
                      <span className="material-symbols-outlined text-error text-[20px]">lock</span>
                    ) : lesson.isCompleted ? (
                      <span className="material-symbols-outlined text-secondary text-[20px]">check_circle</span>
                    ) : (
                      <span className="material-symbols-outlined text-on-surface-variant/50 text-[20px]">radio_button_unchecked</span>
                    )}
                  </div>
                  <div className="flex-1">
                    <h4 className={`text-sm font-semibold mb-1 ${activeLesson.id === lesson.id ? 'text-primary-fixed' : ''} ${lesson.isLockedByTutor ? 'opacity-50' : ''}`}>
                      {index + 1}. {lesson.title}
                    </h4>
                    <span className={`text-xs opacity-80 flex items-center gap-1 ${lesson.isLockedByTutor ? 'opacity-50' : ''}`}>
                      <span className="material-symbols-outlined text-[14px]">schedule</span>
                      {lesson.duration}
                    </span>
                  </div>
                </button>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}
